import sys, heapq

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    p = 1
    lists = {}
    cnt = {}
    heap = []
    out = []
    for _ in range(q):
        op = data[p]
        if op == 'TOP':
            k = int(data[p + 1]); p += 2
            got = []
            seen = set()
            while heap and len(got) < k:
                c, s = heapq.heappop(heap)
                c = -c
                if cnt.get(s, 0) != c or s in seen:
                    continue
                seen.add(s)
                got.append((c, s))
            for c, s in got:
                heapq.heappush(heap, (-c, s))
            out.append(' '.join(str(s) for _, s in got) if got else '-1')
        else:
            u = int(data[p + 1]); s = int(data[p + 2]); p += 3
            pl = lists.setdefault(u, set())
            if op == 'ADD':
                if s in pl:
                    continue
                pl.add(s)
                cnt[s] = cnt.get(s, 0) + 1
            else:
                if s not in pl:
                    continue
                pl.remove(s)
                cnt[s] -= 1
            if cnt[s] > 0:
                heapq.heappush(heap, (-cnt[s], s))
    print('\n'.join(out))

